  let templateSearchTimer;byId("page-template-filter").addEventListener("input",()=>{clearTimeout(templateSearchTimer);templateSearchTimer=setTimeout(()=>{pagesCurrentPage=1;renderPages()},200)});
  function architectureCopy(){return locale==="uk"?{label:"Структура сайту",incoming:"Виявлені вхідні посилання",broken:"Посилання на помилки",redirects:"Посилання через перенаправлення",notice:"Враховано лише посилання з перевірених сторінок. Неперевірені URL не вважаються битими.",filters:{"":"Усі сторінки",zero:"Без виявлених вхідних посилань",one:"Одне виявлене вхідне посилання",broken:"Посилаються на помилки",redirects:"Посилаються через перенаправлення",deep:"Глибина 4+"}}:{label:"Site architecture",incoming:"Observed inlinks",broken:"Links to errors",redirects:"Links through redirects",notice:"Only links from checked pages are counted. Unchecked targets are not classified as broken.",filters:{"":"All pages",zero:"No observed inlinks",one:"One observed inlink",broken:"Links to errors",redirects:"Links through redirects",deep:"Depth 4+"}}}
  function matchesArchitecture(page){const query=byId("page-template-filter").value.trim().toLowerCase();if(query&&!(report.pageExplorer.templates[page.template]?.label??"").toLowerCase().includes(query))return false;const filter=byId("page-architecture").value;if(filter==="zero")return page.incoming!==null&&page.incoming.length===0;if(filter==="one")return page.incoming?.length===1;if(filter==="broken")return page.broken?.length>0;if(filter==="redirects")return page.redirects?.length>0;if(filter==="deep")return page.depth!==null&&page.depth>=4;return true}
