  function issuePills(page){const wrap=document.createElement("div");wrap.className="issue-counts";const labels=copy().severities;for(const level of ["error","warning","info"]){if(!page.counts[level])continue;const pill=document.createElement("button");pill.type="button";pill.className="issue-pill "+level;pill.textContent=page.counts[level]+" "+labels[level];pill.addEventListener("click",(event)=>{event.stopPropagation();openIssuesForPage(page,level)});wrap.append(pill)}if(!wrap.childNodes.length)wrap.textContent="—";return wrap}
