  function renderPages(){const text=pageCopy();const query=pageSearch.value.trim().toLowerCase();pagesFiltered=report.pageExplorer.pages.filter((page,index)=>{if(query&&!pageSearchIndex[index].includes(query))return false;if(!matchesArchitecture(page))return false;if(pageStatus.value==="none"&&page.s!==null)return false;if(pageStatus.value&&pageStatus.value!=="none"&&Math.floor(page.s/100)!==Number(pageStatus.value))return false;if(pageIndexability.value&&page.ix!==pageIndexability.value)return false;const total=page.counts.error+page.counts.warning+page.counts.info;if(pageIssues.value==="yes"&&total===0)return false;if(pageIssues.value==="no"&&total!==0)return false;if(["error","warning","info"].includes(pageIssues.value)&&page.counts[pageIssues.value]===0)return false;return true});pagesFiltered.sort((left,right)=>{const a=pageSortValue(left,pageSort.key),b=pageSortValue(right,pageSort.key);if(a===null&&b!==null)return 1;if(b===null&&a!==null)return -1;const compared=typeof a==="number"&&typeof b==="number"?a-b:String(a??"").localeCompare(String(b??""));return compared===0?String(pageUrl(left.u)).localeCompare(String(pageUrl(right.u))):compared*pageSort.direction});for(const button of document.querySelectorAll("[data-page-sort]")){button.closest("th").setAttribute("aria-sort",button.dataset.pageSort===pageSort.key?(pageSort.direction===1?"ascending":"descending"):"none")}const size=Number(pagePageSize.value);const count=Math.max(1,Math.ceil(pagesFiltered.length/size));pagesCurrentPage=Math.min(pagesCurrentPage,count);const visible=pagesFiltered.slice((pagesCurrentPage-1)*size,pagesCurrentPage*size);pagesBody.replaceChildren();for(const page of visible){const row=document.createElement("tr");const urlCell=document.createElement("td");const button=document.createElement("button");button.type="button";button.className="page-url-button";button.textContent=pageUrl(page.u)||"";button.addEventListener("click",()=>openPage(page,button));urlCell.append(button);row.append(urlCell);cell(row,page.s??text.noResponse);const stateCell=document.createElement("td");const state=document.createElement("span");state.className="indexability";state.textContent=text.states[page.ix]||page.ix;stateCell.append(state);row.append(stateCell);cell(row,page.t||"—");cell(row,page.depth??"—");cell(row,page.incoming===null?"—":page.incoming.length);const issueCell=document.createElement("td");issueCell.append(issuePills(page));row.append(issueCell);pagesBody.append(row)}pageResultCount.textContent=number(pagesFiltered.length)+" "+text.of+" "+number(report.pageExplorer.pages.length)+" "+text.pages;pagePageInfo.textContent=text.page+" "+number(pagesCurrentPage)+" "+text.of+" "+number(count);pagePrevious.disabled=pagesCurrentPage===1;pageNext.disabled=pagesCurrentPage===count;pagePagination.hidden=pagesFiltered.length===0||count===1;pagesTableWrap.hidden=pagesFiltered.length===0;pagesEmpty.hidden=pagesFiltered.length!==0}
