  function closePage(){if(pageDialog.hidden)return;pageDialog.hidden=true;pageDialogBackdrop.hidden=true;document.body.style.overflow="";pageReturnFocus?.focus();pageReturnFocus=null}
  function csvSafe(value){const text=String(value??"");return /^[\\t\\r\\n ]*[=+@-]/.test(text)||/^[\\t\\r]/.test(text)?"'"+text:text}
